import { Router, Request, Response, NextFunction } from 'express';
import Post from '../models/post.model';
import db from '../config/database';

const router = Router();

// Middleware để ghi log tất cả các request
router.use((req: Request, res: Response, next: NextFunction) => {
  console.log(`\n=== ${new Date().toISOString()} ===`);
  console.log(`[${req.method}] ${req.originalUrl}`);
  console.log('Base URL:', req.baseUrl);
  console.log('Path:', req.path);
  console.log('Query:', req.query);
  console.log('Headers:', {
    'content-type': req.get('content-type'),
    'authorization': req.get('authorization') ? '***' : undefined,
    'user-agent': req.get('user-agent')
  });
  
  if (Object.keys(req.body).length > 0) {
    console.log('Body:', req.body);
  }
  next();
});

// Route kiểm tra kết nối
router.get(['/test', '/posts/test', '/api/posts/test'], (req: Request, res: Response) => {
  console.log('Đã gọi route kiểm tra');
  res.json({ 
    success: true,
    message: 'Kết nối API Posts Service thành công!',
    timestamp: new Date().toISOString()
  });
});

// GET /posts hoặc /api/posts - Lấy danh sách bài viết
router.get(['/', '/posts', '/api', '/api/posts'], async (req: Request, res: Response) => {
  try {
    console.log('GET /api/posts - Request received');
    console.log('Query params:', req.query);

    // Xử lý tham số truy vấn
    const page = Math.max(1, parseInt(req.query.page as string) || 1);
    const pageSize = parseInt(req.query.page_size as string) || parseInt(req.query.limit as string) || 10;
    const limit = Math.min(100, Math.max(1, pageSize)); // Giới hạn tối đa 100 bản ghi/trang
    const offset = (page - 1) * limit;
    
    // Kiểm tra nếu có yêu cầu lọc theo trạng thái
    const status = req.query.is_published === 'true' ? 'published' : undefined;
    
    // Lấy danh sách bài viết từ database với thông tin phân trang
    const { posts, total, page: currentPage, totalPages } = await Post.findAll({ 
      limit, 
      offset,
      status
    });

    // Trả về kết quả với cấu trúc phù hợp cho frontend
    res.status(200).json({
      success: true,
      data: posts,
      pagination: {
        total,
        page: currentPage,
        pageSize: limit,
        totalPages
      }
    });
  } catch (error) {
    console.error('Error fetching posts:', error);
    res.status(500).json({
      success: false,
      message: 'Đã xảy ra lỗi khi lấy danh sách bài viết',
      error: error instanceof Error ? error.message : 'Lỗi không xác định'
    });
  }
});

// PATCH /posts/:id hoặc /api/posts/:id - Cập nhật bài viết
router.patch(['/:id', '/posts/:id', '/api/posts/:id'], async (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const updateData = req.body;
    
    console.log(`PATCH /api/posts/${id} - Request received`);
    console.log('Update data:', updateData);

    if (!id) {
      return res.status(400).json({
        success: false,
        message: 'Thiếu tham số ID bài viết'
      });
    }

    // Cập nhật bài viết
    const updatedPost = await Post.update(id, updateData);
    
    if (!updatedPost) {
      return res.status(404).json({
        success: false,
        message: 'Không tìm thấy bài viết với ID đã cho'
      });
    }

    // Trả về thông tin bài viết đã cập nhật
    res.status(200).json({
      success: true,
      data: updatedPost
    });
  } catch (error) {
    console.error(`Error updating post ${req.params.id}:`, error);
    res.status(500).json({
      success: false,
      message: 'Đã xảy ra lỗi khi cập nhật bài viết',
      error: error instanceof Error ? error.message : 'Lỗi không xác định'
    });
  }
});

// GET /posts/:id hoặc /api/posts/:id - Lấy thông tin chi tiết bài viết
router.get(['/:id', '/posts/:id', '/api/posts/:id'], async (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    console.log(`GET /api/posts/${id} - Request received`);

    if (!id) {
      return res.status(400).json({
        success: false,
        message: 'Thiếu tham số ID bài viết'
      });
    }

    // Lấy thông tin bài viết từ database
    const post = await Post.findById(id);
    
    if (!post) {
      return res.status(404).json({
        success: false,
        message: 'Không tìm thấy bài viết với ID đã cho'
      });
    }

    // Trả về thông tin bài viết
    res.status(200).json({
      success: true,
      data: post
    });
  } catch (error) {
    console.error(`Error fetching post ${req.params.id}:`, error);
    res.status(500).json({
      success: false,
      message: 'Đã xảy ra lỗi khi lấy thông tin bài viết',
      error: error instanceof Error ? error.message : 'Lỗi không xác định'
    });
  }
});

// POST /api/posts - Tạo bài viết mới
router.post('/', (req: Request, res: Response) => {
  console.log('POST /api/posts - Request received');
  console.log('Request body:', req.body);

  // Kiểm tra các trường bắt buộc
  const { title, content } = req.body;
  if (!title || !content) {
    console.log('Thiếu các trường bắt buộc');
    return res.status(400).json({
      status: 'error',
      message: 'Vui lòng cung cấp đầy đủ tiêu đề và nội dung'
    });
  }

  // Tạo bài viết mới
  const newPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };

  console.log('Đã tạo bài viết thành công');
  res.status(201).json({
    status: 'success',
    message: 'Bài viết đã được tạo',
    data: {
      post: newPost
    }
  });
});

export default router;
